const NL = String.fromCharCode(10);
let queries = String($env.RESEARCH_QUERY || 'soal pilihan ganda kurikulum SD kelas 4 IPAS').split('|').map((q) => q.trim()).filter(Boolean);
let mapel = $env.DEFAULT_MAPEL || 'IPAS';
let jenjang = $env.DEFAULT_JENJANG || 'SD';
let maxQuestions = Number($env.MAX_QUESTIONS || 3);
let maxSearches = Number($env.MAX_SEARCHES_PER_RUN || 2);
let maxResults = Number($env.MAX_RESULTS_PER_QUERY || 3);
let maxTokens = Number($env.MAX_OUTPUT_TOKENS || 1200);

for (const key of ['SEARCH_API_KEY', 'LLM_API_KEY', 'CMS_USERNAME', 'CMS_PASSWORD']) {
  if (!$env[key]) throw new Error(key + ' belum diisi di /etc/n8n.env');
}

const login = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://cms.hanyadi.web.id/api/v1/auth/login',
  body: { username: $env.CMS_USERNAME, password: $env.CMS_PASSWORD },
  json: true,
  returnFullResponse: true
});
const rawCookies = login.headers?.['set-cookie'];
const cookie = Array.isArray(rawCookies)
  ? rawCookies.map((c) => c.split(';')[0]).join('; ')
  : (rawCookies ? String(rawCookies).split(';')[0] : '');
if (!cookie) throw new Error('Login CMS tidak menghasilkan cookie');

let started = null;
try {
  const startedResponse = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://cms.hanyadi.web.id/api/v1/research-agent-usage/start',
    headers: { Cookie: cookie },
    body: {},
    json: true
  });
  started = startedResponse?.data ?? {};
  const cfg = started.config;
  if (cfg?.queries?.length) queries = cfg.queries.map((q) => String(q).trim()).filter(Boolean);
  if (cfg?.mapel) mapel = cfg.mapel;
  if (cfg?.jenjang) jenjang = cfg.jenjang;
  if (cfg?.max_questions) maxQuestions = Number(cfg.max_questions);
  if (cfg?.max_searches) maxSearches = Number(cfg.max_searches);
  if (cfg?.max_results_per_query) maxResults = Number(cfg.max_results_per_query);
  if (cfg?.max_output_tokens) maxTokens = Number(cfg.max_output_tokens);
  if (started.allowed === false) {
    return [{ json: { ok: false, skipped: true, reason: started.reason, remaining: started.remaining } }];
  }
} catch (error) {
  if (!$env.RESEARCH_QUERY) throw new Error('Gagal membaca konfigurasi query dari CMS: ' + error.message);
}

maxQuestions = Math.min(Math.max(1, maxQuestions), 10);
maxSearches = Math.min(Math.max(1, maxSearches), 5);
maxResults = Math.min(Math.max(1, maxResults), 10);
maxTokens = Math.min(Math.max(300, maxTokens), 4000);

const sources = [];
let searchedCount = 0;
for (const query of queries.slice(0, maxSearches)) {
  const search = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.tavily.com/search',
    headers: { Authorization: 'Bearer ' + $env.SEARCH_API_KEY },
    body: { query, max_results: maxResults, search_depth: 'basic' },
    json: true
  });
  searchedCount += 1;
  for (const r of (search.results || [])) {
    if (!sources.some((s) => s.url === r.url)) sources.push({ url: r.url, title: r.title, content: r.content });
  }
}
const context = sources.map((s) => 'SUMBER: ' + s.url + NL + 'JUDUL: ' + s.title + NL + 'ISI: ' + s.content).join(NL + NL);

const rawBase = $env.LLM_BASE_URL || 'https://api.openai.com/v1';
const baseUrl = rawBase.endsWith('/') ? rawBase.slice(0, -1) : rawBase;
const completion = await this.helpers.httpRequest({
  method: 'POST',
  url: baseUrl + '/chat/completions',
  headers: { Authorization: 'Bearer ' + $env.LLM_API_KEY },
  body: {
    model: $env.LLM_MODEL || 'gpt-4o-mini',
    temperature: 0.2,
    max_tokens: maxTokens,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: 'Kamu pembuat soal jenjang ' + jenjang + ' mapel ' + mapel + '. Kembalikan HANYA JSON object dengan kunci questions berisi array soal. Setiap soal punya stem, question_type, difficulty, options [{key,content,is_correct}], correct_keys, answer_text, explanation, confidence. Jika true_false gunakan statements [{text,is_correct}] dan jangan options.' },
      { role: 'user', content: 'Buat ' + maxQuestions + ' soal yang akurat berdasarkan sumber berikut. Sertakan confidence 0 sampai 1.' + NL + NL + context }
    ]
  },
  json: true
});

const raw = completion.choices?.[0]?.message?.content || '{}';
const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
const questions = Array.isArray(parsed.questions) ? parsed.questions : [];
if (!questions.length) return [{ json: { ok: false, reason: 'LLM tidak mengembalikan soal' } }];

const runId = 'n8n-' + Date.now();
const results = [];
for (let i = 0; i < Math.min(maxQuestions, questions.length); i += 1) {
  const q = questions[i];
  const payload = {
    stem: q.stem,
    jenjang,
    mapel,
    question_type: q.question_type || 'multiple_choice',
    difficulty: q.difficulty || 'medium',
    options: q.options || [],
    correct_keys: q.correct_keys || [],
    statements: q.statements || [],
    answer_text: q.answer_text || null,
    explanation: q.explanation || null,
    external_ref: runId + '-' + (i + 1),
    source_url: sources[0]?.url || null,
    metadata: {
      run_id: runId,
      model: $env.LLM_MODEL || 'gpt-4o-mini',
      query: queries,
      confidence: q.confidence ?? null,
      sources: sources.map((s) => s.url)
    }
  };
  try {
    const saved = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://cms.hanyadi.web.id/api/v1/research-submissions',
      headers: { Cookie: cookie },
      body: payload,
      json: true
    });
    results.push({ json: { ok: true, id: saved.submission?.id, status: saved.submission?.status, external_ref: payload.external_ref } });
  } catch (error) {
    results.push({ json: { ok: false, external_ref: payload.external_ref, error: error.message } });
  }
}
try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://cms.hanyadi.web.id/api/v1/research-agent-usage/finish',
    headers: { Cookie: cookie },
    body: {
      searches: searchedCount,
      questions: results.filter((item) => item.json.ok).length
    },
    json: true
  });
} catch (error) {
  results.push({ json: { ok: false, error: 'Gagal mencatat pemakaian: ' + error.message } });
}
return results;
